// Demo: Statistical Sampling Profilers — hotspot ranking from 1 samples
var samples={};for(var i=0;i<1;i++){var f='fn'+((i*31+1)%7);samples[f]=(samples[f]||0)+1;}
var ranked=Object.keys(samples).sort(function(a,b){return samples[b]-samples[a];});
console.log('technique: Statistical Sampling Profilers');
ranked.slice(0,5).forEach(function(f,i){console.log('#'+(i+1)+' '+f+': '+samples[f]+' samples ('+(100*samples[f]/1).toFixed(1)+'%)');});
console.log('hotspot: '+ranked[0]+' — optimize here first');

// Demo: eBPF Kernel Tracing — latency percentile attribution
var spans=[];for(var i=0;i<9;i++){spans.push({svc:'svc'+((i*17+2)%4),ms:5+((i*41)%(15%200+50))});}
spans.sort(function(a,b){return a.ms-b.ms;});var p99=spans[Math.floor(spans.length*0.99)].ms;
var worst={};spans.filter(function(s){return s.ms>=p99;}).forEach(function(s){worst[s.svc]=(worst[s.svc]||0)+1;});
console.log('technique: eBPF Kernel Tracing');console.log('p99 latency: '+p99+' ms');
console.log('tail contributors: '+JSON.stringify(worst));

